-- | Replays @differential/custody_corpus.json@ (generated by the reference)
-- and checks the custody port against it byte for byte: the SQLite schema
-- text, key-context authenticated data, payload decoding, and seeded
-- scripted sessions (every step's outcome, revision, payload, and files).
module Petrus.Agenticus.CustodyCorpusSpec (spec) where

import Control.Exception (finally)
import Control.Monad (forM_)
import Data.ByteString qualified as B
import Data.Text (Text)
import Data.Text qualified as T
import Petrus.Agenticus.Connection.Key
import Petrus.Agenticus.Connection.Storage
import Petrus.Agenticus.ConnectionSupport (withScratch)
import Petrus.Agenticus.CustodyScript
import Petrus.Agenticus.Error
import Petrus.Agenticus.Internal.Sqlite qualified as Sql
import Petrus.Agenticus.Support (loadJson)
import Petrus.Json (Json (..))
import Petrus.Json qualified as J
import System.FilePath ((</>))
import Test.Hspec

spec :: Spec
spec = describe "differential: custody_corpus.json" $ do
  corpus <- runIO (loadJson "differential/custody_corpus.json")

  it "a fresh store's sqlite_master text and initial row" $ withScratch $ \scratch -> do
    let path = scratch </> "store" </> "connections.sqlite3"
    storage <- openSqliteConnectionStorage path
    storage.close
    master <- sqliteRows path "SELECT type, name, tbl_name, sql FROM sqlite_master ORDER BY name"
    rows <- sqliteRows path "SELECT singleton, revision, payload FROM connection_custody"
    let reference = member "schema" corpus
    master `shouldSatisfy` J.exactEq (member "sqlite_master" reference)
    rows `shouldSatisfy` J.exactEq (member "rows" reference)

  it "KeyContext validation and authenticated_data" $
    forM_ (members (member "key_contexts" corpus)) $ \c -> do
      let outcome = case mkKeyContext (str "connection_id" c) (int "authority_epoch" c) (int "state_version" c) of
            Right keyContext -> Object [("ok", String (hex (authenticatedData keyContext)))]
            Left failure -> Object [("error", refusal failure)]
      canonical (withoutInputs c) `shouldSatisfy` J.exactEq (canonical outcome)

  describe "payload decoding" $
    forM_ (members (member "payload_cases" corpus)) $ \c ->
      it (T.unpack (str "name" c)) $ do
        let outcome = case decodeSnapshot (str "payload" c) >>= encodeSnapshot of
              Right text -> Object [("ok", String text)]
              Left failure -> Object [("error", refusal failure)]
        canonical outcome `shouldSatisfy` J.exactEq (canonical (withoutKeys ["name", "payload"] c))

  describe "scripted sessions" $
    forM_ (members (member "sessions" corpus)) $ \session ->
      it ("seed " <> show (int "seed" session)) $ withScratch $ \scratch -> do
        let steps = members (member "steps" session)
            expected = members (member "records" session)
        actual <- runSteps scratch steps 0 (length steps)
        compareRecords steps 0 expected actual

sqliteRows :: FilePath -> Text -> IO Json
sqliteRows path query = do
  database <- Sql.openDatabase path
  ( do
      statement <- Sql.prepareStatement database query
      rows <- Sql.queryRows statement [] `finally` Sql.finalizeStatement statement
      pure (Array [Array (map cell row) | row <- rows])
    )
    `finally` Sql.closeDatabase database
  where
    cell = \case
      Sql.SQLInteger n -> Int (toInteger n)
      Sql.SQLText t -> String t
      Sql.SQLNull -> Null
      other -> error ("unexpected sqlite value " <> show other)

refusal :: AgenticusError -> Json
refusal failure = Object [("class", String (errorClassName failure.errorClass)), ("message", String failure.errorMessage)]

withoutInputs :: Json -> Json
withoutInputs = withoutKeys ["connection_id", "authority_epoch", "state_version"]

withoutKeys :: [Text] -> Json -> Json
withoutKeys names = \case
  Object fields -> Object [field | field@(name, _) <- fields, name `notElem` names]
  other -> other

str :: Text -> Json -> Text
str name value = case member name value of
  String t -> t
  other -> error ("expected a string at " <> T.unpack name <> ", got " <> show other)

int :: Text -> Json -> Integer
int name value = case member name value of
  Int n -> n
  other -> error ("expected an integer at " <> T.unpack name <> ", got " <> show other)

hex :: B.ByteString -> Text
hex = T.concat . map byte . B.unpack
  where
    byte w = T.pack [digits !! fromIntegral (w `div` 16), digits !! fromIntegral (w `mod` 16)]
    digits = "0123456789abcdef"
